import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"API Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/api-dashboard.md","filePath":"web-app/api-dashboard.md"}'),i={name:"web-app/api-dashboard.md"};function s(d,e,n,l,h,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="api-dashboard" tabindex="-1">API Dashboard <a class="header-anchor" href="#api-dashboard" aria-label="Permalink to &quot;API Dashboard&quot;">​</a></h1><p>Open <strong>API Dashboard</strong> from the app menu to manage keys for the <a href="./../api/">public API</a>. Your API key identifies your account; keep it private and use separate keys for separate integrations.</p><h2 id="keys-and-folders" tabindex="-1">Keys and folders <a class="header-anchor" href="#keys-and-folders" aria-label="Permalink to &quot;Keys and folders&quot;">​</a></h2><ul><li>Create a <code>sk_live_</code> key and copy the full value immediately. It is shown only once.</li><li>Give each key a descriptive nickname and optionally group it in a folder.</li><li>Review its preview, creation date, status and available credits.</li><li>Revoke a key you no longer use to prevent further authentication.</li></ul><table tabindex="0"><thead><tr><th>Plan</th><th>Active keys</th></tr></thead><tbody><tr><td>Free</td><td>3</td></tr><tr><td>Pro</td><td>20</td></tr><tr><td>Dev</td><td>Unlimited</td></tr></tbody></table><p>Revoked keys do not occupy an active-key slot. See <a href="./../api/authentication.html">Authentication</a> for using a key safely.</p><h2 id="credits-and-usage" tabindex="-1">Credits and usage <a class="header-anchor" href="#credits-and-usage" aria-label="Permalink to &quot;Credits and usage&quot;">​</a></h2><p>The dashboard shows each key&#39;s available API credits. Public API requests consume credits according to the <a href="./../api/errors.html#credits">endpoint costs</a>. An empty key balance may use an available App Credit and return <code>X-Credit-Warning</code>; surface that warning in your integration.</p><p>API credit purchases and money-wallet top-ups are unavailable. A donation is not a credit purchase. Check the account&#39;s displayed balance before making requests; do not assume a future plan or purchase will add credits.</p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><p>Replay the API Dashboard tour from <a href="./settings.html#tutorials">Settings → Tutorials</a>. For failed requests, check the API <a href="./../api/errors.html">errors and response headers</a>.</p>',11)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
